51	    private static int getHash(String string) {
52	        final int p = 16777619;
53	        int hash = (int)2166136261L;
54	        for(int i = 0; i < string.length(); i ++) {
55	            hash = (hash ^ string.charAt(i)) * p;
56	        }
57	        hash += hash << 13;
58	        hash ^= hash >> 7;
59	        hash += hash << 3;
60	        hash ^= hash >> 17;
61	        hash += hash << 5;
62	        if(hash < 0) {
63	            hash = Math.abs(hash);
64	        }
65	        return hash;
66	    }
