126	    private static String getServer(String ip) {
127	        int hash = getHash(ip);
128	        SortedMap<Integer, String> tailMap = virtualNodes.tailMap(hash);
129	        Integer targetKey = 0;
130	        if(!tailMap.isEmpty()) {
131	            targetKey = tailMap.firstKey();
132	        }
133	        String virtualNodeName = tailMap.get(targetKey);
134	        return virtualNodeName.substring(0, virtualNodeName.indexOf("##"));
135	    }
136	
137	    private static void deleteServer(String ip) {
138	        realNodes.remove(ip);
139	        for(int i = 0; i < NUMBER_OF_VIRTUAL_NODES; i ++) {
140	            String virtualNodeName = ip + "##VN" + String.valueOf(i);
141	            int hash = getHash(virtualNodeName);
142	            virtualNodes.remove(hash);
143	        }
144	    }
145	}

