import java.lang.reflect.*;
import java.util.*;

public class Probe {
    public static void main(String[] a) throws Exception {
        Class<?> c = Class.forName("Main");
        Method addVN = c.getDeclaredMethod("addVirtualNode", String.class);
        Method getHash = c.getDeclaredMethod("getHash", String.class);
        Method getServer = c.getDeclaredMethod("getServer", String.class);
        Method delSrv = c.getDeclaredMethod("deleteServer", String.class);
        for (Method m : new Method[]{addVN,getHash,getServer,delSrv}) m.setAccessible(true);
        Field fVN = c.getDeclaredField("virtualNodes"); fVN.setAccessible(true);
        Field fRN = c.getDeclaredField("realNodes");    fRN.setAccessible(true);
        TreeMap<Integer,String> vn = (TreeMap<Integer,String>) fVN.get(null);
        LinkedList<String> rn = (LinkedList<String>) fRN.get(null);

        String[] servers = {"10.0.0.1","10.0.0.2","10.0.0.3","10.0.0.4"};
        for (String s : servers) { rn.add(s); addVN.invoke(null, s); }
        System.out.println("servers=" + rn.size() + " virtualNodes=" + vn.size()
            + " expected=" + (10*rn.size()) + " OK=" + (vn.size()==10*rn.size()));

        // ring keys strictly ascending (TreeMap invariant) + all distinct
        int prev = Integer.MIN_VALUE; boolean asc = true;
        for (int k : vn.keySet()) { if (k <= prev) asc=false; prev=k; }
        System.out.println("ring keys strictly ascending & distinct: " + asc);

        // successor invariant: getServer(x) == owner of smallest key >= hash(x)
        int checked=0, bad=0, wrapNPE=0;
        for (int i=0;i<20000;i++) {
            String key = "client-" + i;
            int h = (Integer) getHash.invoke(null, key);
            Map.Entry<Integer,String> e = vn.ceilingEntry(h);
            if (e == null) { wrapNPE++; continue; }   // past ring end
            String expect = e.getValue().substring(0, e.getValue().indexOf("##"));
            String actual = (String) getServer.invoke(null, key);
            checked++;
            if (!expect.equals(actual)) { bad++; if(bad<4) System.out.println("MISMATCH "+key+" exp="+expect+" act="+actual); }
        }
        System.out.println("successor invariant: checked="+checked+" mismatches="+bad+" beyond-ring-end="+wrapNPE);

        // load distribution across virtual nodes
        Map<String,Integer> load = new TreeMap<>();
        for (String s : servers) load.put(s,0);
        for (int i=0;i<20000;i++){
            int h=(Integer)getHash.invoke(null,"client-"+i);
            Map.Entry<Integer,String> e=vn.ceilingEntry(h);
            if(e==null) continue;
            String s=e.getValue().substring(0,e.getValue().indexOf("##"));
            load.put(s, load.get(s)+1);
        }
        System.out.println("load distribution: " + load);

        // remap stability: delete one server, count how many keys move
        Map<String,String> before = new HashMap<>();
        for (int i=0;i<20000;i++){ int h=(Integer)getHash.invoke(null,"client-"+i);
            Map.Entry<Integer,String> e=vn.ceilingEntry(h); if(e!=null) before.put("client-"+i, e.getValue().substring(0,e.getValue().indexOf("##"))); }
        delSrv.invoke(null, "10.0.0.2");
        System.out.println("after delete: servers="+rn.size()+" virtualNodes="+vn.size()+" OK="+(vn.size()==10*rn.size()));
        int moved=0, movedOffDeleted=0, movedOther=0;
        for (Map.Entry<String,String> en : before.entrySet()){
            int h=(Integer)getHash.invoke(null,en.getKey());
            Map.Entry<Integer,String> e=vn.ceilingEntry(h); if(e==null) continue;
            String now=e.getValue().substring(0,e.getValue().indexOf("##"));
            if(!now.equals(en.getValue())){ moved++; if(en.getValue().equals("10.0.0.2")) movedOffDeleted++; else movedOther++; }
        }
        System.out.println("keys remapped="+moved+" (off deleted server="+movedOffDeleted+", spurious moves among surviving servers="+movedOther+")");
    }
}
